function count_trailing_zeros_or_ones(val_64bit):
  bit0 = val_64bit & 1
  count = 0
  for i = 0 to 63:
    if ((val_64bit >> i) & 1) == bit0:
      count = count + 1
    else:
      break
  if count > 63:
    count = 63
  return count

function count_leading_zeros_or_ones(val_64bit):
  bit63 = (val_64bit >> 63) & 1
  count = 0
  for i = 63 down to 0:
    if ((val_64bit >> i) & 1) == bit63:
      count = count + 1
    else:
      break
  if count > 63:
    count = 63
  return count

function generate_digest(reg_type, val_64bit):
  if reg_type == INT:
    trailing_count = count_trailing_zeros_or_ones(val_64bit) & 0x3F
    leading_count = count_leading_zeros_or_ones(val_64bit) & 0x3F
    lsb6 = val_64bit & 0x3F
    digest = (trailing_count) ^ (leading_count << 3) ^ (lsb6 << 6)
    return digest & 0x0FFF
  else if reg_type == FP:
    // Inspect MSBs to classify FP format
    if is_fp16(val_64bit):
      // Val[15:13] placed at digest[5:3]
      fp16_val = ((val_64bit >> 13) & 0x7) << 3
      return fp16_val
    else if is_fp32(val_64bit):
      // Val[31:26] placed at digest[8:3]
      fp32_val = ((val_64bit >> 26) & 0x3F) << 3
      return fp32_val
    else: // FP64
      // Val[63:55] placed at digest[11:3]
      fp64_val = ((val_64bit >> 55) & 0x1FF) << 3
      return fp64_val
  else if reg_type == FLAG:
    // Replicate 4 condition flags 3 times into 12 bits
    flags = val_64bit & 0xF
    flag_val = (flags << 8) | (flags << 4) | flags
    return flag_val
  return 0

function predict_sR(PC):
  sR_sum = 0
  for bank = 0 to 7:
    // Bank registers: r = bank + 8 * k, for k >= 0 while r < 65
    regs_in_bank = [r for r in 0..64 if (r % 8) == bank]

    // 1. Calculate usefulness for each register in the bank
    idx0 = hash_ut0(PC); idx1 = hash_ut1(PC); idx2 = hash_ut2(PC)
    best_reg = -1
    max_useful = -9999

    for r in regs_in_bank:
      if register_status_table[r].valid == 1:
        u = usefulness_weight_tables[bank].UT0[idx0][r] +
            usefulness_weight_tables[bank].UT1[idx1][r] +
            usefulness_weight_tables[bank].UT2[idx2][r]
        if u > max_useful:
          max_useful = u
          best_reg = r

    // 2. Query weight tables if an available register was found
    if best_reg != -1:
      digest = register_status_table[best_reg].payload[11:0]
      h0 = hash_wt0(PC, digest)
      h1 = hash_wt1(PC, digest)
      h2 = hash_wt2(PC, digest)

      wt_sum = prediction_weight_tables[bank].WT0[h0] +
               prediction_weight_tables[bank].WT1[h1] +
               prediction_weight_tables[bank].WT2[h2]

      // Apply per-bank multiplier: x2.5 if bank is useful (max_useful > 0), else x0
      if max_useful > 0:
        scaled_sum = (wt_sum * 5) / 2 // Integer arithmetic for 2.5x
      else:
        scaled_sum = 0
      sR_sum += scaled_sum

  return sR_sum

function sat_add_signed_6bit(val, step):
  res = val + step
  if res > 31:
    return 31
  if res < -32:
    return -32
  return res

function update_sR(PC, outcome, recorded_valid_regs_at_pred, recorded_selected_regs):
  for bank = 0 to 7:
    available_regs = [r for r in recorded_valid_regs_at_pred if (r % 8 == bank)]
    if len(available_regs) == 0:
      continue

    // If multiple registers were available, randomly select one to update
    r_update = available_regs[random_choice(len(available_regs))]
    digest = recorded_digest[r_update]

    // Update weight tables WT0, WT1, WT2 using perceptron rule
    h0 = hash_wt0(PC, digest); h1 = hash_wt1(PC, digest); h2 = hash_wt2(PC, digest)
    step = (outcome == TAKEN) ? +1 : -1
    prediction_weight_tables[bank].WT0[h0] = sat_add_signed_6bit(prediction_weight_tables[bank].WT0[h0], step)
    prediction_weight_tables[bank].WT1[h1] = sat_add_signed_6bit(prediction_weight_tables[bank].WT1[h1], step)
    prediction_weight_tables[bank].WT2[h2] = sat_add_signed_6bit(prediction_weight_tables[bank].WT2[h2], step)

    // Update usefulness tables UT0, UT1, UT2
    // Usefulness increments if WT direction agreed with outcome, else decrements
    wt_sum = prediction_weight_tables[bank].WT0[h0] + prediction_weight_tables[bank].WT1[h1] + prediction_weight_tables[bank].WT2[h2]
    pred_agreed = ((wt_sum >= 0) == (outcome == TAKEN))
    u_step = pred_agreed ? +1 : -1
    idx0 = hash_ut0(PC); idx1 = hash_ut1(PC); idx2 = hash_ut2(PC)
    usefulness_weight_tables[bank].UT0[idx0][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT0[idx0][r_update], u_step)
    usefulness_weight_tables[bank].UT1[idx1][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT1[idx1][r_update], u_step)
    usefulness_weight_tables[bank].UT2[idx2][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT2[idx2][r_update], u_step)

function on_decode(rd, rob_index):
  for r = 0 to 64:
    if register_status_table[r].valid == 1:
      register_status_table[r].decay_ctr = register_status_table[r].decay_ctr + 1
      if register_status_table[r].decay_ctr >= 256:
        register_status_table[r].valid = 0
  if rd >= 0 and rd < 65:
    register_status_table[rd].valid = 0
    register_status_table[rd].payload = rob_index & 0x3FFF // 14-bit tag
    register_status_table[rd].decay_ctr = 0

function on_instruction_decoded_tick():
  for r = 0 to 64:
    if register_status_table[r].valid == 1:
      if register_status_table[r].decay_ctr < 255:
        register_status_table[r].decay_ctr += 1
      else:
        // 256 instructions elapsed; digest is stale
        register_status_table[r].valid = 0

function on_squash(flushed_rob_indices):
  for r = 0 to 64:
    if register_status_table[r].valid == 0:
      if register_status_table[r].payload in flushed_rob_indices:
        // Producer instruction was flushed; mark entry invalid or revert
        register_status_table[r].valid = 0
        register_status_table[r].payload = 0
